const ahora = new Date();
const hace24Horas = new Date(ahora.getTime() - 24 * 60 * 60 * 1000);

return {
  fecha_actual: ahora.toISOString(),
  fecha_24h_antes: hace24Horas.toISOString()
};

const pagos = $input.all().map(item => item.json);

if (pagos.length === 0) {
  return {
    hay_pagos: false,
    mensaje: 'No hay nuevos pagos Bold en las ultimas 24 horas'
  };
}

let resumen = '💰 *RESUMEN DIARIO DE PAGOS BOLD*\n\n';
resumen += `📅 Periodo: ${new Date().toLocaleDateString('es-CO')}\n\n`;
resumen += `📦 Total de pagos: ${pagos.length}\n\n`;
resumen += `💵 Monto total: $${pagos.reduce((sum, p) => sum + parseFloat(p.total_amount || 0), 0).toLocaleString('es-CO')}\n\n`;

// Lista de pagos
pagos.forEach((pago, index) => {
  const hora = new Date(pago.paid_at).toLocaleTimeString('es-CO', { hour: '2-digit', minute: '2-digit' });
  const metodoPago = {
    'card': 'Tarjeta',
    'nequi': 'Nequi',
    'pse': 'PSE',
    'daviplata': 'Daviplata'
  }[pago.bold_payment_method] || pago.bold_payment_method || 'N/A';

  resumen += `📌 *Pago ${index + 1}*\n`;
  resumen += `👤 ${pago.guest_name || 'N/A'}\n`;
  resumen += `📞 ${pago.guest_phone || 'N/A'}\n`;
  resumen += `💵 $${parseFloat(pago.total_amount || 0).toLocaleString('es-CO')} - ${metodoPago}\n`;
  resumen += `🔖 ${pago.bold_transaction_id || 'N/A'}\n`;
  resumen += `⏰ ${hora}\n\n`;
});

return {
  hay_pagos: true,
  cantidad: pagos.length,
  monto_total: pagos.reduce((sum, p) => sum + parseFloat(p.total_amount || 0), 0),
  mensaje: resumen
};
